-- Title: DSInternals Suspicious PowerShell Cmdlets
-- ID: 43d91656-a9b2-4541-b7e2-6a9bd3a13f4e
-- Status: test
-- Level: high
-- Author: Nasreddine Bencherchali (Nextron Systems), Nounou Mbeiri
-- Date: 2024-06-26
-- Tags: attack.execution, attack.t1059.001
-- Description: Detects execution and usage of the DSInternals PowerShell module. Which can be used to perform what might be considered as suspicious activity such as dumping DPAPI backup keys or manipulating NTDS.DIT files.
-- The DSInternals PowerShell Module exposes several internal features of Active Directory and Azure Active Directory. These include FIDO2 and NGC key auditing, offline ntds.dit file manipulation, password auditing, DC recovery from IFM backups and password hash calculation.
-- Converted by: Sigma Universal SIEM/EDR CLI

SELECT * FROM processes WHERE ((CommandLine LIKE '%Add-ADDBSidHistory%' OR CommandLine LIKE '%Add-ADNgcKey%' OR CommandLine LIKE '%Add-ADReplNgcKey%' OR CommandLine LIKE '%ConvertFrom-ADManagedPasswordBlob%' OR CommandLine LIKE '%ConvertFrom-GPPrefPassword%' OR CommandLine LIKE '%ConvertFrom-ManagedPasswordBlob%' OR CommandLine LIKE '%ConvertFrom-UnattendXmlPassword%' OR CommandLine LIKE '%ConvertFrom-UnicodePassword%' OR CommandLine LIKE '%ConvertTo-AADHash%' OR CommandLine LIKE '%ConvertTo-GPPrefPassword%' OR CommandLine LIKE '%ConvertTo-KerberosKey%' OR CommandLine LIKE '%ConvertTo-LMHash%' OR CommandLine LIKE '%ConvertTo-MsoPasswordHash%' OR CommandLine LIKE '%ConvertTo-NTHash%' OR CommandLine LIKE '%ConvertTo-OrgIdHash%' OR CommandLine LIKE '%ConvertTo-UnicodePassword%' OR CommandLine LIKE '%Disable-ADDBAccount%' OR CommandLine LIKE '%Enable-ADDBAccount%' OR CommandLine LIKE '%Get-ADDBAccount%' OR CommandLine LIKE '%Get-ADDBBackupKey%' OR CommandLine LIKE '%Get-ADDBDomainController%' OR CommandLine LIKE '%Get-ADDBGroupManagedServiceAccount%' OR CommandLine LIKE '%Get-ADDBKdsRootKey%' OR CommandLine LIKE '%Get-ADDBSchemaAttribute%' OR CommandLine LIKE '%Get-ADDBServiceAccount%' OR CommandLine LIKE '%Get-ADDefaultPasswordPolicy%' OR CommandLine LIKE '%Get-ADKeyCredential%' OR CommandLine LIKE '%Get-ADPasswordPolicy%' OR CommandLine LIKE '%Get-ADReplAccount%' OR CommandLine LIKE '%Get-ADReplBackupKey%' OR CommandLine LIKE '%Get-ADReplicationAccount%' OR CommandLine LIKE '%Get-ADSIAccount%' OR CommandLine LIKE '%Get-AzureADUserEx%' OR CommandLine LIKE '%Get-BootKey%' OR CommandLine LIKE '%Get-KeyCredential%' OR CommandLine LIKE '%Get-LsaBackupKey%' OR CommandLine LIKE '%Get-LsaPolicy%' OR CommandLine LIKE '%Get-SamPasswordPolicy%' OR CommandLine LIKE '%Get-SysKey%' OR CommandLine LIKE '%Get-SystemKey%' OR CommandLine LIKE '%New-ADDBRestoreFromMediaScript%' OR CommandLine LIKE '%New-ADKeyCredential%' OR CommandLine LIKE '%New-ADNgcKey%' OR CommandLine LIKE '%New-NTHashSet%' OR CommandLine LIKE '%Remove-ADDBObject%' OR CommandLine LIKE '%Save-DPAPIBlob%' OR CommandLine LIKE '%Set-ADAccountPasswordHash%' OR CommandLine LIKE '%Set-ADDBAccountPassword%' OR CommandLine LIKE '%Set-ADDBBootKey%' OR CommandLine LIKE '%Set-ADDBDomainController%' OR CommandLine LIKE '%Set-ADDBPrimaryGroup%' OR CommandLine LIKE '%Set-ADDBSysKey%' OR CommandLine LIKE '%Set-AzureADUserEx%' OR CommandLine LIKE '%Set-LsaPolicy%' OR CommandLine LIKE '%Set-SamAccountPasswordHash%' OR CommandLine LIKE '%Set-WinUserPasswordHash%' OR CommandLine LIKE '%Test-ADDBPasswordQuality%' OR CommandLine LIKE '%Test-ADPasswordQuality%' OR CommandLine LIKE '%Test-ADReplPasswordQuality%' OR CommandLine LIKE '%Test-PasswordQuality%' OR CommandLine LIKE '%Unlock-ADDBAccount%' OR CommandLine LIKE '%Write-ADNgcKey%' OR CommandLine LIKE '%Write-ADReplNgcKey%'))
